    momentum_body_nms->y = 0.0;
    momentum_body_nms->z = 0.0;

    for (size_t i = 0; i < count; i++) {
        adcs_vec3_t axis;

        // Validate inertia: finite and > 0
        if (!isfinite(wheels[i].inertia_kg_m2) || wheels[i].inertia_kg_m2 <= 0.0) {
            momentum_body_nms->x = 0.0;
            momentum_body_nms->y = 0.0;
            momentum_body_nms->z = 0.0;
            return ADCS_E_RANGE;
        }

        // Validate speed: finite
        if (!isfinite(wheels[i].speed_rad_s)) {
            momentum_body_nms->x = 0.0;
            momentum_body_nms->y = 0.0;
            momentum_body_nms->z = 0.0;
            return ADCS_E_RANGE;
        }

        // Validate axis: finite vector
        if (!adcs_is_finite_vec3(&wheels[i].axis_body)) {
            momentum_body_nms->x = 0.0;
            momentum_body_nms->y = 0.0;
            momentum_body_nms->z = 0.0;
            return ADCS_E_RANGE;
        }

        // Normalize axis: must be non-zero (non-degenerate)
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK) {
            momentum_body_nms->x = 0.0;
            momentum_body_nms->y = 0.0;
            momentum_body_nms->z = 0.0;
            return ADCS_E_RANGE;
        }

        // Compute h_k = J_k * omega_k * a_k
        double scalar = wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s;
        adcs_vec3_t term = adcs_vec3_scale(&axis, scalar);

        // Accumulate in index order
        *momentum_body_nms = adcs_vec3_add(momentum_body_nms, &term);
    }

    return ADCS_OK;
}

