        momentum_body_nms->x = 0.0;
        momentum_body_nms->y = 0.0;
        momentum_body_nms->z = 0.0;
        return ADCS_E_RANGE;
    }

    /* 3. Validate complete array first */
    for (i = 0; i < count; i++) {
        current_axis = wheels[i].axis_body;
        inertia = wheels[i].inertia_kg_m2;
        speed = wheels[i].speed_rad_s;

        /* Check finiteness of all scalar and vector components */
        if (!isfinite(inertia) || !isfinite(speed) || !adcs_is_finite_vec3(&current_axis)) {
            momentum_body_nms->x = 0.0;
            momentum_body_nms->y = 0.0;
            momentum_body_nms->z = 0.0;
            return ADCS_E_RANGE;
        }

        /* Check positive inertia */
        if (inertia <= 0.0) {
            momentum_body_nms->x = 0.0;
            momentum_body_nms->y = 0.0;
            momentum_body_nms->z = 0.0;
            return ADCS_E_RANGE;
        }

        /* Validate that axis can be normalized (non-zero norm) */
        if (adcs_vec3_normalize(&current_axis, ADCS_EPS_NORM, &axis_norm) != ADCS_OK) {
            momentum_body_nms->x = 0.0;
            momentum_body_nms->y = 0.0;
            momentum_body_nms->z = 0.0;
            return ADCS_E_RANGE;
        }
    }

    /* 4. Accumulate in index order */
    for (i = 0; i < count; i++) {
        current_axis = wheels[i].axis_body;
        inertia = wheels[i].inertia_kg_m2;
        speed = wheels[i].speed_rad_s;

        /* Normalize axis again for calculation */
        adcs_vec3_normalize(&current_axis, ADCS_EPS_NORM, &axis_norm);

        /* Compute h_k = J_k * omega_k * a_k */
        scale_factor = inertia * speed;
        h_k = adcs_vec3_scale(&axis_norm, scale_factor);

        /* Add to total */
        total_h = adcs_vec3_add(&total_h, &h_k);
    }

    /* 5. Output result */
    *momentum_body_nms = total_h;
    return ADCS_OK;
}

